def removeAllOccurrences(s, part):
    m = len(part)
    fail = [0] * m
    k = 0
    for i in range(1, m):
        while k and part[i] != part[k]:
            k = fail[k - 1]
        if part[i] == part[k]:
            k += 1
        fail[i] = k
    chars = []
    states = [0]
    for ch in s:
        k = states[-1]
        while k and part[k] != ch:
            k = fail[k - 1]
        if part[k] == ch:
            k += 1
        chars.append(ch)
        states.append(k)
        if k == m:
            del chars[-m:]
            del states[-m:]
    return "".join(chars)
